def transform(grid):
    H, W = len(grid), len(grid[0])
    if H == 0: return []

    # Count colors to find background
    counts = {}
    for r in range(H):
        for c in range(W):
            color = grid[r][c]
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)

    # Find 3x3 uniform blocks of non-background color
    blocks = []
    for r in range(H-2):
        for c in range(W-2):
            color = grid[r][c]
            if color == background:
                continue
            is_block = True
            for dr in range(3):
                for dc in range(3):
                    if grid[r+dr][c+dc] != color:
                        is_block = False
                        break
                if not is_block:
                    break
            if is_block:
                blocks.append((r+1, c+1))  # Center

    # Output dimensions: ~4x4 scaling like demo
    out_rows = (H + 3) // 4
    out_cols = (W + 3) // 4
    if out_rows < 1: out_rows = 1
    if out_cols < 1: out_cols = 1

    output = [[background]*out_cols for _ in range(out_rows)]

    for br, bc in blocks:
        orr = br // 4
        occ = bc // 4
        if 0 <= orr < out_rows and 0 <= occ < out_cols:
            output[orr][occ] = 1

    return output
